Class Card
  Private Define balance As Integer;

  Method Constructor(initial As Integer)
    This.balance <- 0;
    If initial > 0 Then
      This.balance <- initial;
    EndIf
  EndMethod

  Method Charge(amount As Integer) As Boolean
    If amount <= 0 Or amount > This.balance Then
      Return False;
    EndIf
    This.balance <- This.balance - amount;
    Return True;
  EndMethod

  Method Load(amount As Integer) As Boolean
    If amount <= 0 Then
      Return False;
    EndIf
    This.balance <- This.balance + amount;
    Return True;
  EndMethod

  Method Balance() As Integer
    Return This.balance;
  EndMethod
EndClass

Algorithm Tests
  Define initial, charge, load As Integer;
  Read initial;
  Read charge;
  Read load;
  Define card As Card <- New Card(initial);
  Write card.Charge(charge), " ", card.Load(load), " ", card.Balance();
EndAlgorithm

